import{_ as r,o as a,c as e,ae as d}from"./chunks/framework.CkRokae0.js";const b=JSON.parse('{"title":"C4 モデルとは","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/03-c4/what-is-c4.md","filePath":"sessions/03-c4/what-is-c4.md"}'),o={name:"sessions/03-c4/what-is-c4.md"};function n(s,t,l,i,h,c){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="c4-モデルとは" tabindex="-1">C4 モデルとは <a class="header-anchor" href="#c4-モデルとは" aria-label="Permalink to &quot;C4 モデルとは&quot;">​</a></h1><h2 id="本質-複雑さを段階的に説明する" tabindex="-1">本質：複雑さを段階的に説明する <a class="header-anchor" href="#本質-複雑さを段階的に説明する" aria-label="Permalink to &quot;本質：複雑さを段階的に説明する&quot;">​</a></h2><p>大規模なシステムを 1つの図で説明しようとすると、複雑すぎて逆にわかりにくくなります。</p><p>C4 モデルは、同じシステムを <strong>4つの異なるズームレベル</strong>で描くことで、段階的に理解できるようにした手法です。</p><h2 id="_4つのレベル" tabindex="-1">4つのレベル <a class="header-anchor" href="#_4つのレベル" aria-label="Permalink to &quot;4つのレベル&quot;">​</a></h2><table tabindex="0"><thead><tr><th>レベル</th><th>対象</th><th>視点</th><th>例</th></tr></thead><tbody><tr><td><strong>Level 1: Context（コンテキスト）</strong></td><td>システム全体と外部システム</td><td>経営層・営業</td><td>ユーザー、外部API、連携システム</td></tr><tr><td><strong>Level 2: Container（コンテナ）</strong></td><td>システム内の主要な部分（アプリ、DB等）</td><td>アーキテクト・チームリード</td><td>Web App、Mobile App、API Server、Database</td></tr><tr><td><strong>Level 3: Component（コンポーネント）</strong></td><td>コンテナ内の主要な機能モジュール</td><td>開発者</td><td>ユーザー管理、注文処理、在庫管理</td></tr><tr><td><strong>Level 4: Code（コード）</strong></td><td>クラス・メソッドレベルの詳細</td><td>実装者</td><td>Java クラス図、シーケンス図</td></tr></tbody></table><h2 id="他の図解手法との違い" tabindex="-1">他の図解手法との違い <a class="header-anchor" href="#他の図解手法との違い" aria-label="Permalink to &quot;他の図解手法との違い&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手法</th><th>対象</th><th>使い所</th></tr></thead><tbody><tr><td><strong>ER図</strong></td><td>データベース構造</td><td>DB 設計段階、正規化の検討</td></tr><tr><td><strong>シーケンス図</strong></td><td>処理の流れ</td><td>API 呼び出しの順序、トランザクション設計</td></tr><tr><td><strong>状態図</strong></td><td>オブジェクトの状態遷移</td><td>ワークフロー、ステートマシン</td></tr><tr><td><strong>C4 モデル</strong></td><td>システム全体の構造と関係性</td><td>全体像を伝える、新メンバーのオンボーディング</td></tr></tbody></table><h2 id="c4-が活躍する場面" tabindex="-1">C4 が活躍する場面 <a class="header-anchor" href="#c4-が活躍する場面" aria-label="Permalink to &quot;C4 が活躍する場面&quot;">​</a></h2><ul><li><strong>新メンバーのオンボーディング</strong>：「このシステム、何で構成されてるんですか？」が 1図で説明できる</li><li><strong>クライアント・経営層への説明</strong>：技術者以外にもシステム全体を伝えやすい</li><li><strong>リファクタリング・再設計検討</strong>：現状の構造を整理し、どこを変えるか視覚化</li><li><strong>マイクロサービス化の検討</strong>：Container を見て「どう分割するか」を考えやすい</li></ul><h2 id="c4-が不要な場面" tabindex="-1">C4 が不要な場面 <a class="header-anchor" href="#c4-が不要な場面" aria-label="Permalink to &quot;C4 が不要な場面&quot;">​</a></h2><ul><li><strong>小規模なシステム</strong>（機能が 3-4 個程度）</li><li><strong>既に図が充実している</strong>（ER図や シーケンス図で十分伝わっている）</li><li><strong>ドキュメント管理が習慣でない組織</strong></li></ul><hr><p><a href="./why-c4.html">次へ: なぜ使うか →</a> · <a href="./">C4トップへ</a></p>',14)])])}const _=r(o,[["render",n]]);export{b as __pageData,_ as default};
